/// The zero value has no size, so use `NewInputFlags` before setting a flag on it. Decoded values are always sized.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct InputFlags {
    /// The set.
    pub set: bool,
    /// The size.
    pub size: i64,
    /// The ids.
    pub ids: Vec<i32>,
}

