/// `InventoryAction` represents a single action that took place during an inventory transaction. On itself, this inventory action is always unbalanced: It must be combined with other actions in an inventory transaction to form a balanced transaction.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct InventoryAction {
    /// `SourceType` is the source type of the inventory action. It is one of the constants above.
    pub source_type: u32,
    /// `WindowID` is the ID of the window that the client has opened. The window ID is not set if the `SourceType` is `InventoryActionSourceWorld`.
    pub window_id: Option<i8>,
    /// `SourceFlags` is a combination of flags that is only set if the `SourceType` is `InventoryActionSourceWorld`.
    pub source_flags: Option<u32>,
    /// `InventorySlot` is the slot in which the action took place. Each action only describes the change of item in a single slot.
    pub inventory_slot: u32,
    /// `OldItem` is the item that was present in the slot before the inventory action. It should be checked by the server to ensure the inventories were not out of sync.
    pub old_item: ItemInstance,
    /// `NewItem` is the new item that was put in the `InventorySlot` that the `OldItem` was in. It must be checked in combination with other inventory actions to ensure that the transaction is balanced.
    pub new_item: ItemInstance,
}

impl Codec for InventoryAction {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        Ok(Self {
            source_type: r.varuint32()?,
            window_id: if r.bool()? { Some(r.int8()?) } else { None },
            source_flags: if r.bool()? {
                Some(r.varuint32()?)
            } else {
                None
            },
            inventory_slot: r.varuint32()?,
            old_item: r.item_instance()?,
            new_item: r.item_instance()?,
        })
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.varuint32(self.source_type);
        w.bool(self.window_id.is_some());
        if let Some(v) = self.window_id {
            w.int8(v);
        }
        w.bool(self.source_flags.is_some());
        if let Some(v) = self.source_flags {
            w.varuint32(v);
        }
        w.varuint32(self.inventory_slot);
        w.item_instance(&self.old_item)?;
        w.item_instance(&self.new_item)?;
        Ok(())
    }
}

/// `InventoryTransactionData` represents an object that holds data specific to an inventory transaction type. The data it holds depends on the type.
#[derive(Debug, Clone, PartialEq)]
pub enum InventoryTransactionData {
    /// The [`NormalTransactionData`] variant.
    Normal(NormalTransactionData),
    /// The [`MismatchTransactionData`] variant.
    Mismatch(MismatchTransactionData),
    /// The [`UseItemTransactionData`] variant.
    UseItem(Box<UseItemTransactionData>),
    /// The [`UseItemOnEntityTransactionData`] variant.
    UseItemOnEntity(Box<UseItemOnEntityTransactionData>),
    /// The [`ReleaseItemTransactionData`] variant.
    ReleaseItem(Box<ReleaseItemTransactionData>),
}

impl Default for InventoryTransactionData {
    fn default() -> Self {
        Self::Normal(NormalTransactionData::default())
    }
}

impl InventoryTransactionData {
    /// The variant with this ID and default fields (gophertunnel `lookupTransactionData`), or `None` for an unknown ID.
    pub fn from_id(id: u32) -> Option<Self> {
        Some(match id {
            0 => Self::Normal(NormalTransactionData::default()),
            1 => Self::Mismatch(MismatchTransactionData::default()),
            2 => Self::UseItem(Box::default()),
            3 => Self::UseItemOnEntity(Box::default()),
            4 => Self::ReleaseItem(Box::default()),
            _ => return None,
        })
    }

    /// The id of the variant (gophertunnel `lookupTransactionDataType`).
    pub fn id(&self) -> u32 {
        match self {
            Self::Normal(_) => 0,
            Self::Mismatch(_) => 1,
            Self::UseItem(_) => 2,
            Self::UseItemOnEntity(_) => 3,
            Self::ReleaseItem(_) => 4,
        }
    }

    /// Reads the body of the same variant.
    pub(crate) fn decode_variant(&self, r: &mut Reader<'_>) -> Result<Self> {
        Ok(match self {
            Self::Normal(_) => Self::Normal(NormalTransactionData::decode(r)?),
            Self::Mismatch(_) => Self::Mismatch(MismatchTransactionData::decode(r)?),
            Self::UseItem(_) => Self::UseItem(Box::new(UseItemTransactionData::decode(r)?)),
            Self::UseItemOnEntity(_) => {
                Self::UseItemOnEntity(Box::new(UseItemOnEntityTransactionData::decode(r)?))
            }
            Self::ReleaseItem(_) => {
                Self::ReleaseItem(Box::new(ReleaseItemTransactionData::decode(r)?))
            }
        })
    }

    /// Writes the body of the variant.
    pub(crate) fn encode_variant(&self, w: &mut Writer) -> Result<()> {
        match self {
            Self::Normal(x) => x.encode(w),
            Self::Mismatch(x) => x.encode(w),
            Self::UseItem(x) => x.encode(w),
            Self::UseItemOnEntity(x) => x.encode(w),
            Self::ReleaseItem(x) => x.encode(w),
        }
    }
}

/// `ItemDescriptor` represents a type of item descriptor. This is one of the concrete types below. It is an alias of Marshaler.
#[derive(Debug, Clone, PartialEq)]
pub enum ItemDescriptor {
    /// The [`InvalidItemDescriptor`] variant.
    Invalid(InvalidItemDescriptor),
    /// The [`DefaultItemDescriptor`] variant.
    Default(DefaultItemDescriptor),
    /// The [`MolangItemDescriptor`] variant.
    Molang(MolangItemDescriptor),
    /// The [`ItemTagItemDescriptor`] variant.
    ItemTag(ItemTagItemDescriptor),
}

impl Default for ItemDescriptor {
    fn default() -> Self {
        Self::Invalid(InvalidItemDescriptor::default())
    }
}

impl ItemDescriptor {
    /// The variant with this ID and default fields (gophertunnel `itemDescriptorFromType`), or `None` for an unknown ID.
    pub fn from_id(id: u8) -> Option<Self> {
        Some(match id {
            0 => Self::Invalid(InvalidItemDescriptor::default()),
            1 => Self::Default(DefaultItemDescriptor::default()),
            2 => Self::Molang(MolangItemDescriptor::default()),
            3 => Self::ItemTag(ItemTagItemDescriptor::default()),
            _ => return None,
        })
    }

    /// The id of the variant (gophertunnel `itemDescriptorType`).
    pub fn id(&self) -> u8 {
        match self {
            Self::Invalid(_) => 0,
            Self::Default(_) => 1,
            Self::Molang(_) => 2,
            Self::ItemTag(_) => 3,
        }
    }

    /// The type name of the variant (gophertunnel `itemDescriptorType`).
    pub fn type_name(&self) -> &'static str {
        match self {
            Self::Invalid(_) => "empty",
            Self::Default(_) => "name",
            Self::Molang(_) => "molang",
            Self::ItemTag(_) => "item_tag",
        }
    }

    /// Reads the body of the same variant.
    pub(crate) fn decode_variant(&self, r: &mut Reader<'_>) -> Result<Self> {
        Ok(match self {
            Self::Invalid(_) => Self::Invalid(InvalidItemDescriptor::decode(r)?),
            Self::Default(_) => Self::Default(DefaultItemDescriptor::decode(r)?),
            Self::Molang(_) => Self::Molang(MolangItemDescriptor::decode(r)?),
            Self::ItemTag(_) => Self::ItemTag(ItemTagItemDescriptor::decode(r)?),
        })
    }

    /// Writes the body of the variant.
    pub(crate) fn encode_variant(&self, w: &mut Writer) -> Result<()> {
        match self {
            Self::Invalid(x) => x.encode(w),
            Self::Default(x) => x.encode(w),
            Self::Molang(x) => x.encode(w),
            Self::ItemTag(x) => x.encode(w),
        }
    }
}

