/// `StackRequestAction` represents a single action related to the inventory present in an `ItemStackRequest`. The action is one of the concrete types below, each of which are indicative of a different action by the client, such as moving an item around the inventory or placing a block. It is an alias of Marshaler.
#[derive(Debug, Clone, PartialEq)]
pub enum StackRequestAction {
    /// The [`TakeStackRequestAction`] variant.
    Take(TakeStackRequestAction),
    /// The [`PlaceStackRequestAction`] variant.
    Place(PlaceStackRequestAction),
    /// The [`SwapStackRequestAction`] variant.
    Swap(SwapStackRequestAction),
    /// The [`DropStackRequestAction`] variant.
    Drop(DropStackRequestAction),
    /// The [`DestroyStackRequestAction`] variant.
    Destroy(DestroyStackRequestAction),
    /// The [`ConsumeStackRequestAction`] variant.
    Consume(ConsumeStackRequestAction),
    /// The [`CreateStackRequestAction`] variant.
    Create(CreateStackRequestAction),
    /// The [`LabTableCombineStackRequestAction`] variant.
    LabTableCombine(LabTableCombineStackRequestAction),
    /// The [`BeaconPaymentStackRequestAction`] variant.
    BeaconPayment(BeaconPaymentStackRequestAction),
    /// The [`MineBlockStackRequestAction`] variant.
    MineBlock(MineBlockStackRequestAction),
    /// The [`CraftRecipeStackRequestAction`] variant.
    CraftRecipe(CraftRecipeStackRequestAction),
    /// The [`AutoCraftRecipeStackRequestAction`] variant.
    AutoCraftRecipe(AutoCraftRecipeStackRequestAction),
    /// The [`CraftCreativeStackRequestAction`] variant.
    CraftCreative(CraftCreativeStackRequestAction),
    /// The [`CraftRecipeOptionalStackRequestAction`] variant.
    CraftRecipeOptional(CraftRecipeOptionalStackRequestAction),
    /// The [`CraftGrindstoneRecipeStackRequestAction`] variant.
    CraftGrindstoneRecipe(CraftGrindstoneRecipeStackRequestAction),
    /// The [`CraftLoomRecipeStackRequestAction`] variant.
    CraftLoomRecipe(CraftLoomRecipeStackRequestAction),
    /// The [`CraftNonImplementedStackRequestAction`] variant.
    CraftNonImplemented(CraftNonImplementedStackRequestAction),
    /// The [`CraftResultsDeprecatedStackRequestAction`] variant.
    CraftResultsDeprecated(CraftResultsDeprecatedStackRequestAction),
}

impl Default for StackRequestAction {
    fn default() -> Self {
        Self::Take(TakeStackRequestAction::default())
    }
}

impl StackRequestAction {
    /// The variant with this ID and default fields (gophertunnel `lookupStackRequestAction`), or `None` for an unknown ID.
    pub fn from_id(id: u8) -> Option<Self> {
        Some(match id {
            0 => Self::Take(TakeStackRequestAction::default()),
            1 => Self::Place(PlaceStackRequestAction::default()),
            2 => Self::Swap(SwapStackRequestAction::default()),
            3 => Self::Drop(DropStackRequestAction::default()),
            4 => Self::Destroy(DestroyStackRequestAction::default()),
            5 => Self::Consume(ConsumeStackRequestAction::default()),
            6 => Self::Create(CreateStackRequestAction::default()),
            9 => Self::LabTableCombine(LabTableCombineStackRequestAction::default()),
            10 => Self::BeaconPayment(BeaconPaymentStackRequestAction::default()),
            11 => Self::MineBlock(MineBlockStackRequestAction::default()),
            12 => Self::CraftRecipe(CraftRecipeStackRequestAction::default()),
            13 => Self::AutoCraftRecipe(AutoCraftRecipeStackRequestAction::default()),
            14 => Self::CraftCreative(CraftCreativeStackRequestAction::default()),
            15 => Self::CraftRecipeOptional(CraftRecipeOptionalStackRequestAction::default()),
            16 => Self::CraftGrindstoneRecipe(CraftGrindstoneRecipeStackRequestAction::default()),
            17 => Self::CraftLoomRecipe(CraftLoomRecipeStackRequestAction::default()),
            18 => Self::CraftNonImplemented(CraftNonImplementedStackRequestAction::default()),
            19 => Self::CraftResultsDeprecated(CraftResultsDeprecatedStackRequestAction::default()),
            _ => return None,
        })
    }

    /// The id of the variant (gophertunnel `lookupStackRequestActionType`).
    pub fn id(&self) -> u8 {
        match self {
            Self::Take(_) => 0,
            Self::Place(_) => 1,
            Self::Swap(_) => 2,
            Self::Drop(_) => 3,
            Self::Destroy(_) => 4,
            Self::Consume(_) => 5,
            Self::Create(_) => 6,
            Self::LabTableCombine(_) => 9,
            Self::BeaconPayment(_) => 10,
            Self::MineBlock(_) => 11,
            Self::CraftRecipe(_) => 12,
            Self::AutoCraftRecipe(_) => 13,
            Self::CraftCreative(_) => 14,
            Self::CraftRecipeOptional(_) => 15,
            Self::CraftGrindstoneRecipe(_) => 16,
            Self::CraftLoomRecipe(_) => 17,
            Self::CraftNonImplemented(_) => 18,
            Self::CraftResultsDeprecated(_) => 19,
        }
    }

    /// Reads the body of the same variant.
    pub(crate) fn decode_variant(&self, r: &mut Reader<'_>) -> Result<Self> {
        Ok(match self {
            Self::Take(_) => Self::Take(TakeStackRequestAction::decode(r)?),
            Self::Place(_) => Self::Place(PlaceStackRequestAction::decode(r)?),
            Self::Swap(_) => Self::Swap(SwapStackRequestAction::decode(r)?),
            Self::Drop(_) => Self::Drop(DropStackRequestAction::decode(r)?),
            Self::Destroy(_) => Self::Destroy(DestroyStackRequestAction::decode(r)?),
            Self::Consume(_) => Self::Consume(ConsumeStackRequestAction::decode(r)?),
            Self::Create(_) => Self::Create(CreateStackRequestAction::decode(r)?),
            Self::LabTableCombine(_) => {
                Self::LabTableCombine(LabTableCombineStackRequestAction::decode(r)?)
            }
            Self::BeaconPayment(_) => {
                Self::BeaconPayment(BeaconPaymentStackRequestAction::decode(r)?)
            }
            Self::MineBlock(_) => Self::MineBlock(MineBlockStackRequestAction::decode(r)?),
            Self::CraftRecipe(_) => Self::CraftRecipe(CraftRecipeStackRequestAction::decode(r)?),
            Self::AutoCraftRecipe(_) => {
                Self::AutoCraftRecipe(AutoCraftRecipeStackRequestAction::decode(r)?)
            }
            Self::CraftCreative(_) => {
                Self::CraftCreative(CraftCreativeStackRequestAction::decode(r)?)
            }
            Self::CraftRecipeOptional(_) => {
                Self::CraftRecipeOptional(CraftRecipeOptionalStackRequestAction::decode(r)?)
            }
            Self::CraftGrindstoneRecipe(_) => {
                Self::CraftGrindstoneRecipe(CraftGrindstoneRecipeStackRequestAction::decode(r)?)
            }
            Self::CraftLoomRecipe(_) => {
                Self::CraftLoomRecipe(CraftLoomRecipeStackRequestAction::decode(r)?)
            }
            Self::CraftNonImplemented(_) => {
                Self::CraftNonImplemented(CraftNonImplementedStackRequestAction::decode(r)?)
            }
            Self::CraftResultsDeprecated(_) => {
                Self::CraftResultsDeprecated(CraftResultsDeprecatedStackRequestAction::decode(r)?)
            }
        })
    }

    /// Writes the body of the variant.
    pub(crate) fn encode_variant(&self, w: &mut Writer) -> Result<()> {
        match self {
            Self::Take(x) => x.encode(w),
            Self::Place(x) => x.encode(w),
            Self::Swap(x) => x.encode(w),
            Self::Drop(x) => x.encode(w),
            Self::Destroy(x) => x.encode(w),
            Self::Consume(x) => x.encode(w),
            Self::Create(x) => x.encode(w),
            Self::LabTableCombine(x) => x.encode(w),
            Self::BeaconPayment(x) => x.encode(w),
            Self::MineBlock(x) => x.encode(w),
            Self::CraftRecipe(x) => x.encode(w),
            Self::AutoCraftRecipe(x) => x.encode(w),
            Self::CraftCreative(x) => x.encode(w),
            Self::CraftRecipeOptional(x) => x.encode(w),
            Self::CraftGrindstoneRecipe(x) => x.encode(w),
            Self::CraftLoomRecipe(x) => x.encode(w),
            Self::CraftNonImplemented(x) => x.encode(w),
            Self::CraftResultsDeprecated(x) => x.encode(w),
        }
    }
}

