/// Waypoint holds optional data for a locator bar waypoint.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Waypoint {
    /// `UpdateFlag` is a bitmask indicating which optional fields are set.
    pub update_flag: u32,
    /// Visible determines whether the waypoint is shown.
    pub visible: Option<bool>,
    /// `WorldPosition` is the position and dimension of the waypoint.
    pub world_position: Option<WaypointWorldPosition>,
    /// `TexturePath` is the resource path for the waypoint icon texture.
    pub texture_path: Option<String>,
    /// `IconSize` is the size of the waypoint icon.
    pub icon_size: Option<[f32; 2]>,
    /// Colour is the RGB colour used to tint the waypoint icon.
    pub colour: Option<i32>,
    /// `ClientPositionAuthority` determines whether the client has authority over the waypoint position.
    pub client_position_authority: Option<bool>,
    /// `ActorUniqueID` is the unique ID of the entity the waypoint tracks.
    pub actor_unique_id: Option<i64>,
}

impl Codec for Waypoint {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        Ok(Self {
            update_flag: r.uint32()?,
            visible: if r.bool()? { Some(r.bool()?) } else { None },
            world_position: if r.bool()? {
                Some(WaypointWorldPosition::decode(r)?)
            } else {
                None
            },
            texture_path: if r.bool()? { Some(r.string()?) } else { None },
            icon_size: if r.bool()? { Some(r.vec2()?) } else { None },
            colour: if r.bool()? { Some(r.int32()?) } else { None },
            client_position_authority: if r.bool()? { Some(r.bool()?) } else { None },
            actor_unique_id: if r.bool()? {
                Some(r.actor_unique_id()?)
            } else {
                None
            },
        })
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.uint32(self.update_flag);
        w.bool(self.visible.is_some());
        if let Some(v) = self.visible {
            w.bool(v);
        }
        w.bool(self.world_position.is_some());
        if let Some(v) = &self.world_position {
            v.encode(w)?;
        }
        w.bool(self.texture_path.is_some());
        if let Some(v) = &self.texture_path {
            w.string(v)?;
        }
        w.bool(self.icon_size.is_some());
        if let Some(v) = self.icon_size {
            w.vec2(v);
        }
        w.bool(self.colour.is_some());
        if let Some(v) = self.colour {
            w.int32(v);
        }
        w.bool(self.client_position_authority.is_some());
        if let Some(v) = self.client_position_authority {
            w.bool(v);
        }
        w.bool(self.actor_unique_id.is_some());
        if let Some(v) = self.actor_unique_id {
            w.actor_unique_id(v);
        }
        Ok(())
    }
}

