/// Reads like gophertunnel `InputFlagList`: `InputFlagList` reads/writes an `InputFlags` holding flags in the range \[0, size) as a list of the `IDs` of the flags that are set. Flag `IDs` must be unique and within range.
pub(crate) fn decode_input_flag_list(
    r: &mut Reader<'_>,
    x: &mut InputFlags,
    size: i64,
) -> Result<()> {
    let count: u32 = r.varuint32()?;
    if count > go_i64_to_u32(size) {
        return Err(Error::InvalidValue {
            field: "player auth input data",
            reason: "too many flags",
        });
    }
    let ids: Vec<i32> = r.list(u64::from(count), Reader::varint32)?;
    for (n, &id) in ids.iter().enumerate() {
        if (id < 0) || (i64::from(id) >= size) {
            return Err(Error::UnknownEnum {
                name: "player auth input data",
                value: i64::from(id),
            });
        } else if go_prefix(&ids, n)?.contains(&id) {
            return Err(Error::InvalidValue {
                field: "player auth input data",
                reason: "flags must be unique",
            });
        }
    }
    *x = InputFlags {
        set: true,
        size,
        ids,
    };
    Ok(())
}

/// Writes like gophertunnel `InputFlagList`: `InputFlagList` reads/writes an `InputFlags` holding flags in the range \[0, size) as a list of the `IDs` of the flags that are set. Flag `IDs` must be unique and within range.
pub(crate) fn encode_input_flag_list(w: &mut Writer, x: &InputFlags, size: i64) -> Result<()> {
    let count: u32 = go_usize_to_u32(x.ids.len());
    w.varuint32(count);
    if count > go_i64_to_u32(size) {
        return Err(Error::InvalidValue {
            field: "player auth input data",
            reason: "too many flags",
        });
    }
    let ids: &Vec<i32> = &x.ids;
    if ids.len() != usize::try_from(count).map_err(|_| Error::Size)? {
        return Err(Error::Size);
    }
    for &v in ids {
        w.varint32(v);
    }
    for (n, &id) in ids.iter().enumerate() {
        if (id < 0) || (i64::from(id) >= size) {
            return Err(Error::UnknownEnum {
                name: "player auth input data",
                value: i64::from(id),
            });
        } else if go_prefix(ids, n)?.contains(&id) {
            return Err(Error::InvalidValue {
                field: "player auth input data",
                reason: "flags must be unique",
            });
        }
    }
    Ok(())
}

/// Reads like gophertunnel `MarshalDataStorePropertyValue`: `MarshalDataStorePropertyValue` encodes/decodes a `DataStorePropertyValue`.
pub(crate) fn decode_marshal_data_store_property_value(
    r: &mut Reader<'_>,
    x: &mut DataStorePropertyValue,
) -> Result<()> {
    x.r#type = r.int32()?;
    match x.r#type {
        0 => {}
        1 => {
            x.bool_value = r.bool()?;
        }
        2 => {
            x.int64_value = r.int64()?;
        }
        3 => {
            x.double_value = r.float64()?;
        }
        4 => {
            x.string_value = r.string()?;
        }
        5 => {
            x.list_value = r.list_varuint32(|r| {
                let mut v = DataStorePropertyValue::default();
                decode_marshal_data_store_property_value(r, &mut v)?;
                Ok(v)
            })?;
        }
        6 => {
            x.map_value = r.list_varuint32(|r| {
                let mut entry = DataStoreMapEntry {
                    key: r.string()?,
                    ..DataStoreMapEntry::default()
                };
                decode_marshal_data_store_property_value(r, &mut entry.value)?;
                Ok(entry)
            })?;
        }
        _ => {
            return Err(Error::UnknownEnum {
                name: "data store property type",
                value: i64::from(x.r#type),
            });
        }
    }
    Ok(())
}

/// Writes like gophertunnel `MarshalDataStorePropertyValue`: `MarshalDataStorePropertyValue` encodes/decodes a `DataStorePropertyValue`.
pub(crate) fn encode_marshal_data_store_property_value(
    w: &mut Writer,
    x: &DataStorePropertyValue,
) -> Result<()> {
    w.int32(x.r#type);
    match x.r#type {
        0 => {}
        1 => {
            w.bool(x.bool_value);
        }
        2 => {
            w.int64(x.int64_value);
        }
        3 => {
            w.float64(x.double_value);
        }
        4 => {
            w.string(&x.string_value)?;
        }
        5 => {
            w.varuint32(length(x.list_value.len())?);
            for v in &x.list_value {
                encode_marshal_data_store_property_value(w, v)?;
            }
        }
        6 => {
            w.varuint32(length(x.map_value.len())?);
            for entry in &x.map_value {
                w.string(&entry.key)?;
                encode_marshal_data_store_property_value(w, &entry.value)?;
            }
        }
        _ => {
            return Err(Error::UnknownEnum {
                name: "data store property type",
                value: i64::from(x.r#type),
            });
        }
    }
    Ok(())
}

