/// Reads like gophertunnel `marshalShaped`.
pub(crate) fn decode_marshal_shaped(r: &mut Reader<'_>, recipe: &mut ShapedRecipe) -> Result<()> {
    recipe.recipe_id = r.string()?;
    recipe.width = r.varint32()?;
    recipe.height = r.varint32()?;
    recipe.input = r.list_varuint32(Reader::item_descriptor_count)?;
    if go_usize_to_i64(recipe.input.len())
        != i64::from(recipe.width).wrapping_mul(i64::from(recipe.height))
    {
        return Err(Error::InvalidValue {
            field: "shaped recipe ingredients",
            reason: "must equal width multiplied by height",
        });
    }
    recipe.output = r.list_varuint32(Reader::item)?;
    recipe.uuid = r.uuid()?;
    recipe.block = r.string()?;
    recipe.priority = r.varint32()?;
    recipe.assume_symmetry = r.bool()?;
    recipe.unlock_requirement = if r.bool()? {
        Some(RecipeUnlockRequirement::decode(r)?)
    } else {
        None
    };
    recipe.recipe_network_id = r.varuint32()?;
    Ok(())
}

/// Writes like gophertunnel `marshalShaped`.
pub(crate) fn encode_marshal_shaped(w: &mut Writer, recipe: &ShapedRecipe) -> Result<()> {
    w.string(&recipe.recipe_id)?;
    w.varint32(recipe.width);
    w.varint32(recipe.height);
    w.varuint32(length(recipe.input.len())?);
    for v in &recipe.input {
        w.item_descriptor_count(v)?;
    }
    if go_usize_to_i64(recipe.input.len())
        != i64::from(recipe.width).wrapping_mul(i64::from(recipe.height))
    {
        return Err(Error::InvalidValue {
            field: "shaped recipe ingredients",
            reason: "must equal width multiplied by height",
        });
    }
    w.varuint32(length(recipe.output.len())?);
    for v in &recipe.output {
        w.item(v)?;
    }
    w.uuid(recipe.uuid);
    w.string(&recipe.block)?;
    w.varint32(recipe.priority);
    w.bool(recipe.assume_symmetry);
    w.bool(recipe.unlock_requirement.is_some());
    if let Some(v) = &recipe.unlock_requirement {
        v.encode(w)?;
    }
    w.varuint32(recipe.recipe_network_id);
    Ok(())
}

/// Reads like gophertunnel `marshalShapeless`.
pub(crate) fn decode_marshal_shapeless(
    r: &mut Reader<'_>,
    recipe: &mut ShapelessRecipe,
) -> Result<()> {
    recipe.recipe_id = r.string()?;
    recipe.input = r.list_varuint32(Reader::item_descriptor_count)?;
    recipe.output = r.list_varuint32(Reader::item)?;
    recipe.uuid = r.uuid()?;
    recipe.block = r.string()?;
    recipe.priority = r.varint32()?;
    recipe.unlock_requirement = if r.bool()? {
        Some(RecipeUnlockRequirement::decode(r)?)
    } else {
        None
    };
    recipe.recipe_network_id = r.varuint32()?;
    Ok(())
}

/// Writes like gophertunnel `marshalShapeless`.
pub(crate) fn encode_marshal_shapeless(w: &mut Writer, recipe: &ShapelessRecipe) -> Result<()> {
    w.string(&recipe.recipe_id)?;
    w.varuint32(length(recipe.input.len())?);
    for v in &recipe.input {
        w.item_descriptor_count(v)?;
    }
    w.varuint32(length(recipe.output.len())?);
    for v in &recipe.output {
        w.item(v)?;
    }
    w.uuid(recipe.uuid);
    w.string(&recipe.block)?;
    w.varint32(recipe.priority);
    w.bool(recipe.unlock_requirement.is_some());
    if let Some(v) = &recipe.unlock_requirement {
        v.encode(w)?;
    }
    w.varuint32(recipe.recipe_network_id);
    Ok(())
}

/// Computes like gophertunnel `personaPieceTintLoginType`: personaPieceTintLoginType converts v2168 wire names back to the persona\_\* names used in login data.
pub(crate) fn persona_piece_tint_login_type(piece_type: &str) -> String {
    if piece_type == "hands" {
        return "persona_hand".to_owned();
    }
    if piece_type == "unsupported" {
        return piece_type.to_owned();
    }
    ["persona_", piece_type].concat()
}

/// Computes like gophertunnel `personaPieceTintWireType`: personaPieceTintWireType converts the persona\_\* names used in login data to the shorter names used by the v2168 skin codec. The hands type is singular in login data but plural on the wire.
pub(crate) fn persona_piece_tint_wire_type(piece_type: &str) -> &str {
    if piece_type == "persona_hand" {
        return "hands";
    }
    piece_type.strip_prefix("persona_").unwrap_or(piece_type)
}

/// Reads like gophertunnel `playerListAction`.
pub(crate) fn decode_player_list_action(r: &mut Reader<'_>, action: &mut u8) -> Result<()> {
    let variant: u32 = r.varuint32()?;
    r.uint8()?;
    *action = 1;
    if variant == 1 {
        *action = 0;
    } else if variant != 0 {
        return Err(Error::UnknownEnum {
            name: "player list entry variant",
            value: i64::from(variant),
        });
    }
    Ok(())
}

/// Writes like gophertunnel `playerListAction`.
pub(crate) fn encode_player_list_action(w: &mut Writer, mut action: u8) -> Result<u8> {
    let mut variant: u32 = 0;
    if action == 0 {
        variant = 1;
    }
    w.varuint32(variant);
    let legacy_action: u8 = action;
    w.uint8(legacy_action);
    action = 1;
    if variant == 1 {
        action = 0;
    } else if variant != 0 {
        return Err(Error::UnknownEnum {
            name: "player list entry variant",
            value: i64::from(variant),
        });
    }
    Ok(action)
}

/// Computes like gophertunnel `stackRequestActionVariant`: stackRequestActionVariant maps an action type to its index in the variant list the action is sent under. The list leaves out the two container actions that are never sent, so the two run out of step above them.
pub(crate) fn stack_request_action_variant(id: u8) -> u32 {
    if id > 8 {
        return u32::from(id).wrapping_sub(2);
    }
    u32::from(id)
}

